 package obstacle;
 
 import effect.ForceFieldEffect;
 import exception.OutsideTheGridException;
 import game.Game;
 import game.Player;
 import grid.Direction;
 import grid.Square;
 
 import java.util.HashSet;
 import java.util.Iterator;
 import java.util.Observable;
 import java.util.Observer;
 import java.util.Set;
 
 /**
  * This class represents a force field, generated by a force field generator.
  * 
  * @invar	A force field starts in the inactive state.
  * 			| new.state = new InactiveForceField()
  * @invar 	A force fields state switches every 2 actions.
  * 			| DURATION = 2
  * 
  * @author 	Groep 8
  * 
  * @version	April 2013
  */
 public class ForceField extends Obstacle implements Observer {
 	
 	/**
 	 * The duration a force field remains in a state.
 	 */
     public static final int DURATION = 2;
 	
     /**
      * The remaining actions left before the force field switches its state.
      */
 	private int actionsLeftBeforeSwitch = DURATION;
 	
 	/**
 	 * A list of players being trapped in the force field.
 	 */
 	private Set<Player> trappedPlayers = new HashSet<Player>();
 	
 	/**
 	 * The state of the force field, this is either active or inactive.
 	 */
 	private ForceFieldState state;
 	
 	/**
 	 * Initialize this new force field as an inactive force field.
 	 * @effect The state is set to inactive
 	 * 			|this.setState(new InactiveForceField())
 	 */
 	public ForceField()
 	{
 		super();
 		this.setState(new InactiveForceField());
 		this.setObserver();
 	}
 	
 	/**
 	 * This method returns the state of the force field.
 	 * 
 	 * @return	The state of the force field.
 	 * 			| return this.state
 	 */
 	public ForceFieldState getState() {
 		return state;
 	}
 
 	/**
 	 * This method sets the state of the force field.
 	 * 
 	 * @param 	state
 	 * 			The new state of the force field.
 	 * 
 	 * @effect	The state is set.
 	 * 			| new.state = state
 	 */
 	protected void setState(ForceFieldState state) {
 		this.state = state;
 	}
 
 	/**
 	 * This method sets the observer for this force field.
 	 * 
 	 * @effect	The action notifier has a new observer.
 	 * 			| Game.getInstance().getActionNofifier().addObserver(this)
 	 */
 	public void setObserver() {
 		Game.getInstance().getActionNotifier().addObserver(this);
 	}
 
 	/**
 	 * Returns the list of trapped players
 	 * 
 	 * @return	trappedPlayers
 	 * 			The list of trapped players.
 	 */
 	public Set<Player> getTrappedPlayers() {
 		return trappedPlayers;
 	}
 
 	/**
 	 * This method adds a player to the list of trapped players.
 	 * 
 	 * @param 	player
 	 * 			This is the player we want to add to the list.
 	 * 
 	 * @effect	The player is added to the list.
 	 * 			| trappedPlayers.add(player)
 	 */
 	public void addTrappedPlayer(Player player) {
 		this.trappedPlayers.add(player);
 	}
 	
 	/**
 	 * Removes a player from the list of trapped players.
 	 * 
 	 * @param 	player
 	 * 			This is the player we want to remove.
 	 * 
 	 * @effect	When the player is in the list, it is removed from the list.
 	 * 			| if(trappedPlayers.contains(player)
 	 * 			| 	trappedPlayers.remove(player)
 	 */
 	public void removeTrappedPlayer(Player player){
 		if(trappedPlayers.contains(player))
 			trappedPlayers.remove(player);
 	}
 	
 	/**
 	 * This method adds all the squares that belong to the force field.
 	 * 
 	 * @param 	start
 	 * 			This is the square where the starting force field generator is located.
 	 * @param 	destination
 	 * 			This is the square where the ending force field generator is located.
 	 * @param 	direction
 	 * 			This is the direction in which the force field is located.
 	 * 
 	 * @effect	All the squares between the start and ending location are added to the force field.
 	 * 			| for each square between start and destination
 	 * 			|	 this.addSquare(square)
 	 */
 	public void addSquares(Square start, Square destination, Direction direction)
 	{
 		this.addSquare(start);
 		Square temp = start;
 		while(temp != destination)
 		{
 			try {
 				temp = temp.getNeighbour(direction);
 			} catch (OutsideTheGridException e) {
 				temp = destination;
 			}
 		this.addSquare(temp);
 		}
 	}
 	
 	/**
 	 * Return whether all squares that this force field covers, point to this force field as their obstacle.
 	 * 
 	 * @return	True if so, false if not.
 	 */
 	public boolean hasProperSquares() {
 		Iterator<Square> it = getSquareList().iterator();
 		Square sq;
 		while(it.hasNext()) {
 			sq = it.next();
 			if (sq.getObstacle() != this) {
 				return false;
 			}
 		}
 		return true;
 	}
 	
 	/**
 	 * This method removes all squares from the force field.
 	 * 
 	 * @effect	The force field has no squares left.
 	 * 			| this.getNbSquares() == 0
 	 */
 	public void removeAllSquares()
 	{
 		while(this.getNbSquares() > 0)
 			removeSquare();
 	}
 	
 	/**
 	 * Add a square to the list of squares that are covered by this force field.
 	 * 
 	 * @param 	square
 	 * 			The square to add to the square list.
 	 * 
 	 * @effect	The square is added to the list of squares.
 	 * 			| squareList.add(square)
 	 * @effect	The added square now has a reference to this obstacle.
 	 * 			| square.setObstacle(this)
 	 * @effect	The added square now has a force field effect.
 	 * 			| square.linkEffect(new ForceFieldEffect())
 	 */
 	@Override
 	public void addSquare(Square square)
 	{
 		super.addSquare(square);
 		if(square != null) square.linkEffect(new ForceFieldEffect());
 	}
 	
 	/**
 	 * Remove the first square from the list of squares that are covered by this force field.
 	 * 
 	 * @param 	square
 	 * 			The square to remove from this force field.
 	 * 
 	 * @effect	The removed square now has not any reference to it anymore.
 	 * 			| squareList.getFirst().setObstacle(null)
 	 * @effect	The first square is removed from the square list.
 	 * 			| squareList.removeFirst()
 	 * @effect	The force field effect is removed from the square.
 	 * 			| getSquareList.getFirst().removeEffect(new ForceFieldEffect())
 	 * 
 	 * @return The square you removed
 	 * 
 	 */
 	@Override
 	public Square removeSquare(){
 		Square s = getSquareList().getFirst();
 		s.removeEffect(new ForceFieldEffect());
 		return super.removeSquare();
 	}
 
 	/**
 	 * This method updates the force field after each action.
 	 * 
 	 * @effect	The remaining actions before switching are lowered.
 	 * 			| actionsLeftBeforeSwitch --
 	 * @effect	If the actions left are 0, the force field switches state, and the actions left are reset.
 	 * 			| if(actionsLeftBeforeSwitch <= 0)
 	 * 			|	getState().switchState(this)
 	 * 			|	actionsLeftBeforeSwitch = DURATION
 	 * @effect	The force field checks whether a player has been trapped twice in this force field.
 	 */
 	@Override
 	public void update(Observable o, Object arg) {
 		actionsLeftBeforeSwitch--;
 		if(actionsLeftBeforeSwitch <= 0){
 			this.getState().switchState(this);
 			actionsLeftBeforeSwitch = DURATION;
 			if(this.getState() instanceof ActiveForceField){
 				for(Square square: getSquareList())
 					if(trappedPlayers.contains(square.getPlayer()))
 						square.getPlayer().setLose(true);
 				trappedPlayers.clear();
 				for(Square square: getSquareList())
 					if(square.getPlayer() != null)
 						trappedPlayers.add(square.getPlayer());
			}
				
 		}
 	}
 
 	/**
 	 * This method returns whether an actor can enter this force field.
 	 * 
 	 * @return 	True if the force field is inactive, otherwise false.
 	 * 			| return getState().canEnter()
 	 */
 	@Override
 	public boolean canEnter() {
 		return getState().canEnter();
 	}
 
 	/**
 	 * This method returns whether an actor can leave this force field.
 	 * 
 	 * @return 	True if the force field is inactive, otherwise false.
 	 * 			| return getState().canLeave()
 	 */
 	@Override
 	public boolean canLeave() {
 		return getState().canLeave();
 	}
 }
